create extension if not exists pgcrypto;
create table if not exists public.projects(id uuid primary key,user_id uuid references auth.users(id) on delete cascade,title text not null,description text default '',script text default '',status text default 'draft',metadata jsonb default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.characters(id uuid primary key,user_id uuid references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,name text not null,role text,profile jsonb default '{}'::jsonb,continuity jsonb default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.scenes(id uuid primary key,user_id uuid references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,title text,graph jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.shots(id uuid primary key,user_id uuid references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,scene_id uuid references public.scenes(id) on delete set null,title text,duration_seconds numeric,camera jsonb default '{}'::jsonb,lighting jsonb default '{}'::jsonb,environment jsonb default '{}'::jsonb,motion jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.assets(id uuid primary key,user_id uuid references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,kind text,version integer default 1,storage_path text,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.jobs(id uuid primary key,user_id uuid references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,type text,status text default 'queued',error_code text,progress numeric default 0,payload jsonb default '{}'::jsonb,result jsonb default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
alter table public.projects enable row level security; alter table public.characters enable row level security; alter table public.scenes enable row level security; alter table public.shots enable row level security; alter table public.assets enable row level security; alter table public.jobs enable row level security;
create policy if not exists projects_owner on public.projects for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists characters_owner on public.characters for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists scenes_owner on public.scenes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists shots_owner on public.shots for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists assets_owner on public.assets for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy if not exists jobs_owner on public.jobs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
